func TestEnumVisibilityInputType(t *testing.T) {
	t.Run("NewFromString_org", func(t *testing.T) {
		t.Parallel()
		val, err := NewVisibilityInputTypeFromString("org")
		assert.NoError(t, err, "valid enum value should not return error")
		assert.Equal(t, VisibilityInputType("org"), val, "enum value should match expected wire value")
	})

	t.Run("NewFromString_user", func(t *testing.T) {
		t.Parallel()
		val, err := NewVisibilityInputTypeFromString("user")
		assert.NoError(t, err, "valid enum value should not return error")
		assert.Equal(t, VisibilityInputType("user"), val, "enum value should match expected wire value")
	})

	t.Run("NewFromString_team", func(t *testing.T) {
		t.Parallel()
		val, err := NewVisibilityInputTypeFromString("team")
		assert.NoError(t, err, "valid enum value should not return error")
		assert.Equal(t, VisibilityInputType("team"), val, "enum value should match expected wire value")
	})

	t.Run("NewFromString_users_and_teams", func(t *testing.T) {
		t.Parallel()
		val, err := NewVisibilityInputTypeFromString("users_and_teams")
		assert.NoError(t, err, "valid enum value should not return error")
		assert.Equal(t, VisibilityInputType("users_and_teams"), val, "enum value should match expected wire value")
	})

	t.Run("NewFromString_Invalid", func(t *testing.T) {
		_, err := NewVisibilityInputTypeFromString("invalid_value_that_does_not_exist")
		assert.Error(t, err)
	})

	t.Run("Ptr", func(t *testing.T) {
		val, err := NewVisibilityInputTypeFromString("org")
		assert.NoError(t, err)
		ptr := val.Ptr()
		assert.NotNil(t, ptr)
		assert.Equal(t, val, *ptr)
	})
}

